-- 10836 criteria of the builds before 5.4, the converter maps them to the criteria trees
CREATE TABLE IF NOT EXISTS `achievement_criteria_legacy` (
  `criteria_id` int unsigned NOT NULL DEFAULT '0',
  `achievement_id` int unsigned NOT NULL DEFAULT '0',
  `type` smallint unsigned NOT NULL DEFAULT '0',
  `asset` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`criteria_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;























